CREATE TEMP TABLE stage0 AS SELECT l.c1,l.c2,l.c3,l.c4,l.c5,l.c6,l.c7,l.c8,r.c601,r.c602,r.c603,r.c604,row_number() OVER (ORDER BY l._ord,r._ord) AS _ord FROM t0 l LEFT JOIN t6 r ON l.c3 = r.c602;
CREATE TEMP TABLE stage1 AS SELECT * FROM stage0 WHERE (c603 = c603);
CREATE TEMP TABLE stage2 AS SELECT CAST(c3 AS BLOB) AS c2000,CAST(c603 AS UBIGINT) AS c2001,_ord FROM stage1;
SELECT hex(c2000),CAST(c2001 AS VARCHAR) FROM stage2 ORDER BY _ord

